const items = $input.all();
const rows = items.map(i => i.json);

const spendByCategory = {};
const spendBySupplier = {};
const suppliersByCategory = {};
const pricesByItem = {};
let preferredSpend = 0;
let nonPreferredSpend = 0;

for (const row of rows) {
  const category = row['Category'] || 'Unknown';
  const supplier = row['Supplier'] || 'Unknown';
  const item = row['Item Description'] || 'Unknown';
  const totalSpend = parseFloat(row['Total Spend']) || 0;
  const unitPrice = parseFloat(row['Unit Price']) || 0;
  const isPreferred = (row['Preferred Supplier'] || '').toString().trim().toLowerCase() === 'yes';

  // Spend by category
  spendByCategory[category] = (spendByCategory[category] || 0) + totalSpend;

  // Spend by supplier
  spendBySupplier[supplier] = (spendBySupplier[supplier] || 0) + totalSpend;

  // Supplier count by category
  if (!suppliersByCategory[category]) {
    suppliersByCategory[category] = new Set();
  }
  suppliersByCategory[category].add(supplier);

  // Price tracking by item
  if (!pricesByItem[item]) {
    pricesByItem[item] = { prices: [], totalQty: 0, totalSpend: 0 };
  }
  pricesByItem[item].prices.push(unitPrice);
  pricesByItem[item].totalQty += parseFloat(row['Quantity']) || 0;
  pricesByItem[item].totalSpend += totalSpend;

  // Preferred vs non-preferred spend
  if (isPreferred) {
    preferredSpend += totalSpend;
  } else {
    nonPreferredSpend += totalSpend;
  }
}

// Compute price stats per item
const itemPriceStats = {};
for (const [item, data] of Object.entries(pricesByItem)) {
  const prices = data.prices;
  const avg = prices.reduce((a, b) => a + b, 0) / prices.length;
  itemPriceStats[item] = {
    averageUnitPrice: Math.round(avg * 100) / 100,
    highestUnitPrice: Math.max(...prices),
    lowestUnitPrice: Math.min(...prices),
    totalSpend: data.totalSpend
  };
}

// Convert suppliersByCategory Sets to counts
const supplierCountByCategory = {};
for (const [cat, suppliers] of Object.entries(suppliersByCategory)) {
  supplierCountByCategory[cat] = suppliers.size;
}

return [{
  json: {
    rawRows: rows,
    spendByCategory,
    spendBySupplier,
    supplierCountByCategory,
    suppliersByCategory: Object.fromEntries(Object.entries(suppliersByCategory).map(([k, v]) => [k, [...v]])),
    itemPriceStats,
    preferredSpend,
    nonPreferredSpend,
    totalSpend: preferredSpend + nonPreferredSpend
  }
}];

const data = $input.first().json;

const {
  rawRows,
  spendByCategory,
  supplierCountByCategory,
  suppliersByCategory,
  itemPriceStats,
  preferredSpend,
  nonPreferredSpend,
  totalSpend
} = data;

const opportunities = [];

/*
=========================================
A. SUPPLIER FRAGMENTATION
=========================================
*/

for (const [category, supplierCount] of Object.entries(supplierCountByCategory)) {

  if (supplierCount > 2) {

    const categorySpend = spendByCategory[category] || 0;

    opportunities.push({
      type: "Supplier Fragmentation",
      category,
      severity:
        supplierCount >= 5 ? "High" :
        supplierCount >= 3 ? "Medium" :
        "Low",

      description:
        `${supplierCount} suppliers are servicing the ${category} category.`,

      supplierCount,
      suppliers: suppliersByCategory[category] || [],
      currentSpend: categorySpend,

      potentialSavings: Math.round(categorySpend * 0.08)
    });
  }
}

/*
=========================================
B. PRICE VARIANCE
=========================================
*/

for (const [item, stats] of Object.entries(itemPriceStats)) {

  const highest = stats.highestUnitPrice;
  const lowest = stats.lowestUnitPrice;
  const spend = stats.totalSpend;

  if (lowest <= 0) continue;

  const variancePct =
    ((highest - lowest) / lowest) * 100;

  if (variancePct > 15) {

    opportunities.push({
      type: "Price Variance",

      item,

      severity:
        variancePct > 40 ? "High" :
        variancePct > 25 ? "Medium" :
        "Low",

      description:
        `${item} shows ${variancePct.toFixed(1)}% price variance.`,

      highestPrice: highest,
      lowestPrice: lowest,
      variancePercent: Number(variancePct.toFixed(2)),
      currentSpend: spend,

      potentialSavings:
        Math.round(spend * (variancePct / 100) * 0.3)
    });
  }
}

/*
=========================================
C. MAVERICK SPEND
=========================================
*/

const maverickByCategory = {};

for (const row of rawRows) {

  const isPreferred =
    (row["Preferred Supplier"] || "")
      .toString()
      .trim()
      .toLowerCase() === "yes";

  if (!isPreferred) {

    const category =
      row["Category"] || "Unknown";

    const spend =
      parseFloat(row["Total Spend"]) || 0;

    maverickByCategory[category] =
      (maverickByCategory[category] || 0) +
      spend;
  }
}

const maverickRate =
  totalSpend > 0
    ? (nonPreferredSpend / totalSpend) * 100
    : 0;

for (const [category, spend] of Object.entries(maverickByCategory)) {

  opportunities.push({
    type: "Maverick Spend",

    category,

    severity:
      maverickRate > 40 ? "High" :
      maverickRate > 20 ? "Medium" :
      "Low",

    description:
      `${category} contains spend with non-preferred suppliers.`,

    currentSpend: spend,
    maverickRate: Number(maverickRate.toFixed(2)),

    potentialSavings:
      Math.round(spend * 0.05)
  });
}

/*
=========================================
D. CONTRACT LEAKAGE
=========================================
*/

const leakageByCategory = {};

for (const row of rawRows) {

  const unitPrice =
    parseFloat(row["Unit Price"]) || 0;

  const contractPrice =
    parseFloat(row["Contract Price"]) || 0;

  const qty =
    parseFloat(row["Quantity"]) || 0;

  if (
    contractPrice > 0 &&
    unitPrice > contractPrice
  ) {

    const leakage =
      (unitPrice - contractPrice) * qty;

    const category =
      row["Category"] || "Unknown";

    if (!leakageByCategory[category]) {

      leakageByCategory[category] = {
        leakageAmount: 0,
        items: []
      };
    }

    leakageByCategory[category].leakageAmount += leakage;

    leakageByCategory[category].items.push(
      row["Item Description"] || "Unknown"
    );
  }
}

for (const [category, details] of Object.entries(leakageByCategory)) {

  opportunities.push({

    type: "Contract Leakage",

    category,

    severity:
      details.leakageAmount > 5000 ? "High" :
      details.leakageAmount > 1000 ? "Medium" :
      "Low",

    description:
      `Purchases exceeded negotiated contract pricing.`,

    affectedItems:
      [...new Set(details.items)],

    leakageAmount:
      Number(details.leakageAmount.toFixed(2)),

    potentialSavings:
      Number(details.leakageAmount.toFixed(2))
  });
}

/*
=========================================
SUMMARY
=========================================
*/

const summary = {
  totalSpend,
  preferredSpend,
  nonPreferredSpend,
  maverickRate:
    Number(
      ((nonPreferredSpend / totalSpend) * 100)
      .toFixed(2)
    ),

  totalOpportunities:
    opportunities.length
};

/*
=========================================
RETURN
=========================================
*/

return [
  {
    json: {
      opportunities,
      summary
    }
  }
];

