const data = $input.first().json;

// OpenAI output structure
const opportunities = data.output?.opportunities || [];

const effortScoreMap = {
  Low: 1,
  Medium: 2,
  High: 3
};

const scored = opportunities.map(opp => {

  const impactScore =
    Number(opp.savingsAmount || 0);

  const effortScore =
    effortScoreMap[opp.effortLevel] || 2;

  const priorityScore =
    impactScore / effortScore;

  let classification;

  if (priorityScore >= 3000) {
    classification = "Strategic Initiative";
  }
  else if (priorityScore >= 1000) {
    classification = "Quick Win";
  }
  else {
    classification = "Low Priority";
  }

  return {
    ...opp,

    impactScore,
    effortScore,

    priorityScore:
      Number(priorityScore.toFixed(2)),

    classification,

    status: "New",

    analysisDate:
      new Date()
      .toISOString()
      .split('T')[0]
  };
});

// Sort highest priority first

scored.sort(
  (a,b) => b.priorityScore - a.priorityScore
);

return scored.map(item => ({
  json: item
}));

const items = $input.all();

const sorted = items.sort((a, b) =>
  (b.json["Priority Score"] || 0) -
  (a.json["Priority Score"] || 0)
);

const top5 = sorted.slice(0, 5);

const totalSavings = top5.reduce(
  (sum, item) => sum + (Number(item.json["Savings Amount"]) || 0),
  0
);

let rows = '';

top5.forEach((item, index) => {

  const opp = item.json;

  let color = '#ffcdd2';

  if (opp["Classification"] === 'Strategic Initiative') {
    color = '#c8e6c9';
  } else if (opp["Classification"] === 'Quick Win') {
    color = '#fff9c4';
  }

  rows += `
<tr>
<td>${index + 1}</td>
<td>${opp["Category"] || ''}</td>
<td>${opp["Opportunity Type"] || ''}</td>
<td>$${Number(opp["Savings Amount"] || 0).toLocaleString()}</td>
<td>${Number(opp["Priority Score"] || 0).toLocaleString()}</td>
<td>
<span style="background:${color};padding:4px 8px;border-radius:4px;">
${opp["Classification"] || ''}
</span>
</td>
<td>${opp["Description"] || ''}</td>
</tr>`;
});

const emailBody = `
<html>
<body>
<h2>Top 5 Procurement Savings Opportunities</h2>

<p>
Total Potential Savings:
<strong>$${totalSavings.toLocaleString()}</strong>
</p>

<table border="1" cellpadding="8" cellspacing="0">
<tr>
<th>#</th>
<th>Category</th>
<th>Opportunity</th>
<th>Savings</th>
<th>Priority Score</th>
<th>Classification</th>
<th>Description</th>
</tr>

${rows}

</table>

</body>
</html>
`;

return [{
  json: {
    subject: 'Procurement Savings Report',
    body: emailBody,
    totalSavings
  }
}];
